#include <limits>
#include <iostream>

void check_limits() {
    using T = int;
    std::cout << "Type T is signed: " << std::numeric_limits<T>::is_signed << "\n";
    std::cout << "T max: " << std::numeric_limits<T>::max() << "\n";
    std::cout << "T min: " << std::numeric_limits<T>::min() << "\n\n";

    using U = unsigned char;
    std::cout << "Type U is signed: " << std::numeric_limits<U>::is_signed << "\n";
    std::cout << "U max: " << (int)std::numeric_limits<U>::max() << "\n";
    std::cout << "U min: " << (int)std::numeric_limits<U>::min() << "\n";
}
